$id=filter_var($_POST['session_id']??null,FILTER_VALIDATE_INT);$activity=filter_var($_POST['activity_id']??null,FILTER_VALIDATE_INT);$type=(string)($_POST['session_type']??'');$title=trim((string)($_POST['title']??''));$starts=trim((string)($_POST['starts_at']??''));$ends=trim((string)($_POST['ends_at']??''));$venue=trim((string)($_POST['venue']??''));$opponent=trim((string)($_POST['opponent']??''));$result=trim((string)($_POST['result']??''));$notes=trim((string)($_POST['notes']??''));$status=(string)($_POST['status']??'Scheduled');$parse=static function(string $v):?DateTimeImmutable{if($v==='')return null;$d=DateTimeImmutable::createFromFormat('!Y-m-d\TH:i',$v);$e=DateTimeImmutable::getLastErrors();return $d!==false&&$d->format('Y-m-d\TH:i')===$v&&($e===false||(!$e['warning_count']&&!$e['error_count']))?$d:null;};$startDate=$parse($starts);$endDate=$parse($ends);
if($id===false||!$activity||!in_array($type,['Practice','Meeting','Fixture','Competition','Trip','Other'],true)||$title===''||strlen($title)>160||!$startDate||($ends!==''&&!$endDate)||($endDate&&$endDate<$startDate)||strlen($venue)>160||strlen($opponent)>140||strlen($result)>100||strlen($notes)>500||!in_array($status,['Scheduled','Completed','Cancelled'],true)){$_SESSION['error']='Check the activity session details and dates.';header('Location: ../?page=activities&activity='.(int)$activity);exit;}
